insert into public.app_announcements select * from jsonb_populate_record(null::public.app_announcements, '{"id": "8c9de486-dbb2-4ad2-a2b4-963d89ea6ea8", "slug": "streambox-june-2026-polish", "body_en": "Actor pages and search are smarter, grids now load as you scroll, filters and profile editing feel smoother, and Cinematic Journeys now includes a corrected James Bond order.", "body_tr": "Oyuncu sayfalari ve arama daha akilli, listeler kaydirdikca yukleniyor, filtreler ve profil duzenleme daha akici, Cinematic Journeys artik duzeltilmis James Bond siralamasini iceriyor.", "cta_url": null, "ends_at": null, "priority": 950, "title_en": "New StreamBox improvements", "title_tr": "Yeni StreamBox iyilestirmeleri", "image_url": null, "is_active": true, "platforms": ["android", "ios"], "starts_at": "2026-06-05T12:14:38.848585+00:00", "accent_hex": "#22C55E", "created_at": "2026-06-05T12:14:38.848585+00:00", "eyebrow_en": "What changed", "eyebrow_tr": "Neler degisti", "updated_at": "2026-06-05T12:14:38.848585+00:00", "cta_label_en": null, "cta_label_tr": null, "requires_auth": false, "display_version": 1, "max_app_version": null, "min_app_version": null}'::jsonb) on conflict do nothing;
insert into public.app_announcements select * from jsonb_populate_record(null::public.app_announcements, E'{"id": "2fc5effe-f38e-42bd-9b03-f69356a3ca9e", "slug": "streambox-letterboxd-import-2026-06", "body_en": "You can now bring your Letterboxd history into StreamBox. Open Settings, choose \\"Import from Letterboxd\\", and pick the .zip you exported from Letterboxd. Your watched films, watchlist and likes are matched and added automatically — watched titles get marked and counted in your stats.", "body_tr": "Artik Letterboxd gecmisini StreamBox''a tasiyabilirsin. Ayarlar bolumunde \\"Letterboxd''dan ice aktar\\" secenegini ac ve Letterboxd''dan disa aktardigin .zip dosyasini sec. Izledigin filmler, izleme listen ve begenilerin otomatik olarak eklenir; izlenen basliklar isaretlenir ve istatistiklerine sayilir.", "cta_url": null, "ends_at": null, "priority": 2600, "title_en": "Import your Letterboxd library", "title_tr": "Letterboxd kutuphaneni ice aktar", "image_url": null, "is_active": true, "platforms": ["android", "ios"], "starts_at": "2026-06-28T19:18:04.433249+00:00", "accent_hex": "#FF8000", "created_at": "2026-06-28T19:18:04.433249+00:00", "eyebrow_en": "New feature", "eyebrow_tr": "Yeni ozellik", "updated_at": "2026-06-28T19:18:04.433249+00:00", "cta_label_en": null, "cta_label_tr": null, "requires_auth": false, "display_version": 1, "max_app_version": null, "min_app_version": null}'::jsonb) on conflict do nothing;
insert into public.app_announcements select * from jsonb_populate_record(null::public.app_announcements, '{"id": "02361aa5-e396-4c97-a652-c94faf1e9c43", "slug": "streambox-new-apk-download-2026-06", "body_en": "A new version is ready with the updated logo, better playback controls, improved ad blocking, faster loading, and a more polished design. Download the latest APK from streamboxapp.stream.", "body_tr": "Yeni logo, daha iyi oynatma kontrolleri, gelismis reklam engelleme, daha hizli yukleme ve daha temiz tasarim iceren yeni surum hazir. En yeni APK dosyasini streamboxapp.stream uzerinden indirin.", "cta_url": "https://streamboxapp.stream", "ends_at": null, "priority": 2500, "title_en": "New StreamBox APK Available", "title_tr": "Yeni StreamBox APK hazir", "image_url": "announcements/new-apk-logo-banner.png", "is_active": false, "platforms": ["android"], "starts_at": "2026-06-11T08:23:59.094421+00:00", "accent_hex": "#22C55E", "created_at": "2026-06-11T08:23:59.094421+00:00", "eyebrow_en": "Update available", "eyebrow_tr": "Guncelleme hazir", "updated_at": "2026-07-02T19:31:21.417842+00:00", "cta_label_en": "Download APK", "cta_label_tr": "APK indir", "requires_auth": false, "display_version": 1, "max_app_version": null, "min_app_version": null}'::jsonb) on conflict do nothing;
